using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        long long sum = 0;
        long long max_cnt = 0;
        for (int i = 0; i < 26; i++) {
            long long x;
            cin >> x;
            sum += x;
            max_cnt = max(max_cnt, x);
        }
        // 答案 = min(sum, 2*(sum - max_cnt) + 1)
        long long ans = min(sum, 2 * (sum - max_cnt) + 1);
        cout << ans << '\n';
    }
    return 0;
}
